/**
 * Everything that can go wrong while constructing a [`Checker`].
 *
 * A rule or binary that fails to load is reported here; nothing panics across the FFI boundary.
 */
public 
enum CheckError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The tokenizer file could not be read from disk.
     */
    case TokenizerFile(message: String
    )
    /**
     * The rules file could not be read from disk.
     */
    case RulesFile(message: String
    )
    /**
     * The tokenizer binary was read but could not be deserialized.
     */
    case Tokenizer(message: String
    )
    /**
     * The rules binary was read but could not be deserialized.
     */
    case Rules(message: String
    )
    /**
     * `profile` named a profile the engine does not know.
     */
    case UnknownProfile(name: String
    )
    /**
     * `spell_variant` named a speller dictionary that is not part of the loaded rules.
     */
    case UnknownSpellVariant(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CheckError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCheckError: FfiConverterRustBuffer {
    typealias SwiftType = CheckError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CheckError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .TokenizerFile(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .RulesFile(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Tokenizer(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Rules(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .UnknownProfile(
            name: try FfiConverterString.read(from: &buf)
            )
        case 6: return .UnknownSpellVariant(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CheckError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .TokenizerFile(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .RulesFile(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Tokenizer(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Rules(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .UnknownProfile(name):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .UnknownSpellVariant(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


